  final List<String> categories = const [
    'All',
    'Nature',
    'Sustainability',
    'Community',
    'Events',
  ];

  String selectedCategory = 'All';

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppColors.background,
      drawer: Header.buildDrawer(context),
      body: Column(
        children: [
          const Header(),
          Expanded(
            child: Column(
              children: [
                _buildCategoryFilter(context),
                Expanded(child: _buildGalleryGrid(context)),
              ],
            ),
          ),
          Footer(),
        ],
      ),
    );
  }

  Widget _buildCategoryFilter(BuildContext context) {
    return Container(
      height: ResponsiveHelper.getScreenHeight(context) * 0.08,
      padding: ResponsiveHelper.getVerticalPadding(context),
      decoration: BoxDecoration(
        color: AppColors.white,
        boxShadow: [
          BoxShadow(
            color: Colors.black.withOpacity(0.05),
            blurRadius: 4,
            offset: Offset(0, 2),
          ),
        ],
      ),
      child: Row(
        children: [
          Expanded(
            child: ListView.builder(
              scrollDirection: Axis.horizontal,
              padding: ResponsiveHelper.getHorizontalPadding(context),
              itemCount: categories.length,
              itemBuilder: (context, index) {
                final category = categories[index];
                final isSelected = category == selectedCategory;
                return Container(
                  margin: EdgeInsets.only(
                    right: ResponsiveHelper.getAdaptiveSpacing(context) * 0.4,
                  ),
                  child: FilterChip(
                    label: Text(
                      category,
                      style: TextStyle(
                        fontSize: ResponsiveHelper.getAdaptiveFontSize(
                          context,
                          baseSize: 14,
                        ),
                        fontWeight:
                            isSelected ? FontWeight.w600 : FontWeight.w500,
                        color:
                            isSelected
                                ? AppColors.white
                                : AppColors.primaryText,
                      ),
                    ),
                    selected: isSelected,
                    onSelected: (_) {
                      setState(() {
                        selectedCategory = category;
                      });
                    },
                    selectedColor: AppColors.success,
                    checkmarkColor: AppColors.white,
                    backgroundColor: AppColors.background,
                    side: BorderSide(
                      color:
                          isSelected
                              ? AppColors.success
                              : AppColors.borderLight,
                      width: 1.5,
                    ),
                    elevation: isSelected ? 2 : 0,
                    shadowColor: AppColors.success.withOpacity(0.3),
                  ),
                );
              },
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildGalleryGrid(BuildContext context) {
    final items =
        selectedCategory == 'All'
            ? galleryItems
            : galleryItems
                .where((item) => item['category'] == selectedCategory)
                .toList();
    if (items.isEmpty) {
      return Center(
        child: Text(
          'No photos found',
          style: TextStyle(color: AppColors.secondaryText),
        ),
      );
    }
    return GridView.builder(
      padding: ResponsiveHelper.getAdaptivePadding(context),
      gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
        crossAxisCount: ResponsiveHelper.getScreenWidth(context) > 600 ? 3 : 2,
        crossAxisSpacing: ResponsiveHelper.getAdaptiveSpacing(context) * 0.4,
        mainAxisSpacing: ResponsiveHelper.getAdaptiveSpacing(context) * 0.4,
        childAspectRatio: 0.8,
      ),
      itemCount: items.length,
      itemBuilder: (context, index) {
        final item = items[index];
        return InkWell(
          onTap: () => _showPhotoDetail(context, item),
          borderRadius: BorderRadius.circular(16),
          child: Card(
            elevation: 4,
            shadowColor: AppColors.success.withOpacity(0.2),
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(16),
            ),
            margin: EdgeInsets.all(8),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Expanded(
                  child: ClipRRect(
                    borderRadius: BorderRadius.vertical(
                      top: Radius.circular(16),
                    ),
                    child: Image.network(
                      item['imageUrl'],
                      width: double.infinity,
                      height: double.infinity,
                      fit: BoxFit.cover,
                      errorBuilder:
                          (context, error, stackTrace) =>
                              Center(child: Icon(Icons.broken_image)),
                    ),
                  ),
                ),
                Container(
                  padding: EdgeInsets.all(12),
                  decoration: BoxDecoration(
                    color: AppColors.white,
                    borderRadius: BorderRadius.vertical(
                      bottom: Radius.circular(16),
                    ),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        item['title'],
                        style: TextStyle(
                          fontSize: ResponsiveHelper.getAdaptiveFontSize(
                            context,
                            baseSize: 16,
                          ),
                          fontWeight: FontWeight.bold,
                          color: AppColors.primaryText,
                        ),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                      ),
                      SizedBox(height: 4),
                      Text(
                        item['description'],
                        style: TextStyle(
                          fontSize: ResponsiveHelper.getAdaptiveFontSize(
                            context,
                            baseSize: 12,
                          ),
                          color: AppColors.secondaryText,
                          height: 1.3,
                        ),
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                      ),
                      SizedBox(height: 8),
                      Row(
                        children: [
                          Container(
                            padding: EdgeInsets.symmetric(
                              horizontal: 8,
                              vertical: 4,
                            ),
                            decoration: BoxDecoration(
                              color: AppColors.success.withOpacity(0.1),
                              borderRadius: BorderRadius.circular(8),
                              border: Border.all(
                                color: AppColors.success.withOpacity(0.3),
                                width: 1,
                              ),
                            ),
                            child: Text(
                              item['category'],
                              style: TextStyle(
                                color: AppColors.success,
                                fontSize: 11,
                                fontWeight: FontWeight.w600,
                              ),
                            ),
                          ),
                          Spacer(),
                          Icon(Icons.favorite, size: 14, color: Colors.red),
                          SizedBox(width: 4),
                          Text(
                            '${item['likes']}',
                            style: TextStyle(fontSize: 12),
                          ),
                          SizedBox(width: 8),
                        ],
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }

  void _showPhotoDetail(BuildContext context, Map<String, dynamic> item) {
    showDialog(
      context: context,
      builder:
          (context) => AlertDialog(
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(16),
            ),
            title: Row(
              children: [
                Icon(Icons.photo, color: AppColors.success),
                SizedBox(width: 8),
                Expanded(
                  child: Text(
                    item['title'],
                    style: TextStyle(
                      fontSize: ResponsiveHelper.getAdaptiveFontSize(
                        context,
                        baseSize: 18,
                      ),
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                ),
              ],
            ),
            content: SingleChildScrollView(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  Container(
                    height: ResponsiveHelper.getScreenHeight(context) * 0.4,
                    width: double.infinity,
                    decoration: BoxDecoration(
                      color: AppColors.background,
                      borderRadius: BorderRadius.circular(
                        ResponsiveHelper.getAdaptiveBorderRadius(context),
                      ),
                    ),
                    child: ClipRRect(
                      borderRadius: BorderRadius.circular(
                        ResponsiveHelper.getAdaptiveBorderRadius(context),
                      ),
                      child: Image.network(
                        item['imageUrl'],
                        fit: BoxFit.cover,
                        errorBuilder:
                            (context, error, stackTrace) =>
                                Center(child: Icon(Icons.broken_image)),
                      ),
                    ),
                  ),
                  SizedBox(
                    height: ResponsiveHelper.getAdaptiveSpacing(context),
                  ),
                  Text(
                    item['description'],
                    style: TextStyle(
                      fontSize: ResponsiveHelper.getAdaptiveFontSize(
                        context,
                        baseSize: 14,
                      ),
                      color: AppColors.secondaryText,
                    ),
                  ),
                  SizedBox(
                    height: ResponsiveHelper.getAdaptiveSpacing(context),
                  ),
                  Row(
                    children: [
                      Icon(
                        Icons.favorite,
                        size: ResponsiveHelper.getAdaptiveIconSize(context),
                        color: AppColors.mutedText,
                      ),
                      SizedBox(
                        width:
                            ResponsiveHelper.getAdaptiveSpacing(context) * 0.2,
                      ),
                      Text(
                        '${item['likes']} likes',
                        style: TextStyle(
                          fontSize: ResponsiveHelper.getAdaptiveFontSize(
                            context,
                            baseSize: 14,
                          ),
                          color: AppColors.secondaryText,
                        ),
                      ),
                      SizedBox(
                        width: ResponsiveHelper.getAdaptiveSpacing(context),
                      ),
                      Container(
                        padding: EdgeInsets.symmetric(
                          horizontal: 8,
                          vertical: 4,
                        ),
                        decoration: BoxDecoration(
                          color: AppColors.success.withOpacity(0.1),
                          borderRadius: BorderRadius.circular(8),
                          border: Border.all(
                            color: AppColors.success.withOpacity(0.3),
                            width: 1,
                          ),
                        ),
                        child: Text(
                          item['category'],
                          style: TextStyle(
                            color: AppColors.success,
                            fontSize: 11,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(context),
                child: Text(
                  'Close',
                  style: TextStyle(
                    fontSize: ResponsiveHelper.getAdaptiveFontSize(
                      context,
                      baseSize: 14,
                    ),
                  ),
                ),
              ),
            ],
          ),
    );
  }
}
